const sectorPath = (index, count) => { const start = polar(50, 50, 42, index * 360 / count); const end = polar(50, 50, 42, (index + 1) * 360 / count); return `M50 50 L${start.x} ${start.y} A42 42 0 ${360 / count > 180 ? 1 : 0} 1 ${end.x} ${end.y} Z`; };

